items=[]
for i, (question, correct, distractors, explanation, source, objective, operation, code) in enumerate(raw, 1):
    correct=correct_revisions.get(i,correct)
    distractors=distractor_revisions.get(i,distractors)
    opts = [correct] + distractors
    target = (i - 1) % 4
    # Rotate the right answer into the planned position without changing the key.
    shift = (0 - target) % 4
    opts = opts[shift:] + opts[:shift]
    correct_index = opts.index(correct)
    row={"id":f"M2L1-{i:03d}","question":question,"options":opts,"correctIndex":correct_index,"expectedAnswer":correct,"explanation":explanation,"source":source,"objective":objective,"operation":operation}
    if code: row["stimulusCode"]=code
    items.append(row)

